class Solution {
public:
    int longestSubsequence(vector<int>& nums) {
        int ans=0;
        for(int bit=0;bit<30;++bit){
            vector<int> tails;
            for(int x:nums) if((x>>bit)&1){
                auto it=lower_bound(tails.begin(),tails.end(),x);
                if(it==tails.end()) tails.push_back(x);
                else *it=x;
            }
            ans=max(ans,(int)tails.size());
        }
        return ans;
    }
};
